import{_ as i,b as r,c as o,g as n}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"电影摄影：理论与实践","description":"","frontmatter":{"title":"电影摄影：理论与实践","subTitle":"电影连续性","author":"oasis","date":"2026-09-22T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/cinematography-theory-and-practice/4.md","filePath":"articles/books/cinematography-theory-and-practice/4.md"}'),s={name:"articles/books/cinematography-theory-and-practice/4.md"};function l(g,t,e,a,d,c){return r(),o("div",null,[...t[0]||(t[0]=[n('<p>连续性是让观众在头脑中重组一个连续现实情景。通过剪辑，让观众感觉到这是同一个时空、同一个地点、同一个动作。只是摄像机变了位置。</p><h2 id="连续性分类" tabindex="-1">连续性分类</h2><ul><li><strong>内容连续性</strong>：前后发生的事情内容要对得上。</li><li><strong>动作连续性</strong>：动作不要在镜头之间断掉。</li><li><strong>位置连续性</strong>：人物 / 物体在空间中的关系不能莫名其妙改变。</li><li><strong>时间连续性</strong>：时间关系要让观众理解。需要思考如何能让观众了解时间的顺序或故事发生的先后顺序。</li></ul><h2 id="画面方向" tabindex="-1">画面方向</h2><ul><li><strong>运动轴线</strong></li><li><strong>180 度区域</strong></li></ul><h2 id="画面分割线的建立" tabindex="-1">画面分割线的建立</h2><p>观众会根据画面中的关系，在脑中建立出来的空间轴线。</p><ul><li><strong>视线</strong>：两个人面对面，他们的视线形成一条分割线。</li><li><strong>移动</strong>：车辆从左向右开，这样也建立了一条分割线，分割了画面的上下空间。</li><li><strong>特定动作</strong></li><li><strong>离开画面</strong>：人物从左或右离开画面，下个镜头应该从相反方向进入画面。</li><li><strong>物理形状</strong>：桌子、公路、树林都会形成分割线。</li></ul><h2 id="连续性的问题" tabindex="-1">连续性的问题</h2><ul><li><strong>移动镜头</strong>：摄影机运动也必须参与空间关系。</li><li><strong>过门镜头</strong></li><li><strong>进入和离开画面</strong>：离开和进入必须保持方向逻辑。</li><li><strong>三人镜头</strong></li><li><strong>保持画面干净</strong>：不要让不必要的东西破坏连续性或遮挡信息。</li><li><strong>备选镜头中的道具连续性</strong>：道具位置要和上一个镜头保持一致。</li><li><strong>扫视</strong>：如果中间切一个镜头，再继续扫视，观众需要知道：我们仍然在同一个空间中扫视。否则空间方向可能混乱。</li><li><strong>群体镜头</strong></li><li><strong>追逐场景</strong>：追逐场景可能出现突然越轴，而破坏连续性。</li><li><strong>旁跳镜头中的视线连续性</strong>：旁跳镜头实际要考虑和主体的关系。</li><li><strong>视线建立新的分割线</strong>：如果人物看向某个东西，视线和东西之间建立了分割线。</li><li><strong>坐姿人物的视线</strong>：身体虽然不动，但是视线仍在建立分割线。</li><li><strong>过肩镜头和插入镜头</strong>：保留人物之间的空间关系。</li><li><strong>移动动作镜头</strong>：用摄影机运动建立、维持或者改变空间关系。</li></ul><h2 id="介绍镜头" tabindex="-1">介绍镜头</h2><h2 id="其他剪辑问题" tabindex="-1">其他剪辑问题</h2><ul><li><strong>跳切</strong>：两个镜头太相似，但时间 / 动作又发生了明显跳跃。跳切可以制作时间压缩、不稳定感、喜剧效果。</li></ul><h2 id="剪辑的类型" tabindex="-1">剪辑的类型</h2><ul><li><strong>内容剪辑</strong>：因为需要新的信息，所以切。</li><li><strong>动作剪辑</strong>：因为动作发生，所以切。在动作结束时切。例如打开罐头盒，可以切到煤气灶的锅。</li><li><strong>视角剪辑</strong>：人物站在某处，然后切到他看向的物体。</li><li><strong>匹配剪辑</strong>：核心是相似性，例如苹果和太阳，它们具有圆形外形。</li><li><strong>概念剪辑</strong>：两个画面本身并不是同一事件，放在一起会产生第三层意义。蒙太奇。</li><li><strong>零点剪辑</strong>：几乎不让观众意识到「发生了一个传统意义上的剪辑」。</li></ul><h2 id="可剪辑性" tabindex="-1">可剪辑性</h2><p>你拍出来的镜头，有没有足够多的「可用部分」，让剪辑师能够自由地把它接到其他镜头上。</p><p>一个动作镜头，最好不要只拍「刚好够用」的长度，而是在动作前后各留出大约 20%～30% 的余量。</p>',18)])])}const _=i(s,[["render",l]]);export{p as __pageData,_ as default};
